  ["demo_tour_messages"] = {
    ["ai_policy_examples_text"] = "Kliknutím na příklad zobrazíte, jak formulovat zásady, nebo níže napište svůj vlastní a popište, jaký provoz sledovat a co se považuje za porušení.",
    ["ai_policy_examples_title"] = "Příklady zásad",
