    ["ai_policy_reach_title"] = "nAnalytik",
    ["ai_policy_table_text"] = "Každá politika, kterou vygenerujete, se zde zobrazí se svou periodicitou, skóre a stavem – upravte je, povolte nebo zakažte jako jakoukoli jinou kontrolu.",
    ["ai_policy_table_title"] = "Vygenerované zásady",
    ["dashboard_badges_text"] = "Výstražné toky, místní hostitelé a aktivní toky na první pohled – kliknutím na jakýkoli odznak přejdete přímo na filtrovaný seznam.",
    ["dashboard_badges_title"] = "Rychlý stav",
    ["dashboard_iface_selector_text"] = "Vyberte monitorované rozhraní, na které se chcete podívat. Vše ostatní na stránce reaguje na tuto volbu.",
    ["dashboard_iface_selector_title"] = "Vyberte Rozhraní",
    ["dashboard_reach_text"] = "Vždy se sem můžete vrátit pomocí ikony Dashboard na postranním panelu.",
    ["dashboard_reach_title"] = "Dashboard",
    ["dashboard_widgets_text"] = "Živý provoz, špičkové aplikace, kvalita a špičkoví řečníci. Živé porty používané s verzemi pro/enterprise a mnohem více. Prozkoumat!",
    ["dashboard_widgets_title"] = "Dopravní panel",
    ["demo_tour_complete_close"] = "Blízko",
    ["demo_tour_complete_text"] = "To je ta prohlídka. Přehrajte si jej kdykoli znovu nebo jej resetujte v části Předvolby → Ukázkové prohlídky.",
    ["demo_tour_complete_title"] = "Vše je připraveno!",
    ["flows_filters_text"] = "Zužte tabulku toků podle hostitele, protokolu, aplikace, stavu, kvality, typu provozu a dalších pomocí rozbalovacích nabídek filtrů nad tabulkou.",
    ["flows_filters_title"] = "Filtrovat živé toky",
    ["flows_table_text"] = "Každé živé síťové připojení aktualizované v reálném čase: protokol, koncové body, propustnost a skóre. Kliknutím na řádek zobrazíte úplné podrobnosti o toku.",
    ["flows_table_title"] = "Tabulka aktivních toků",
    ["historical_filters_text"] = "Přidejte filtry do libovolného indexovaného pole, abyste zúžili historické vyhledávání před spuštěním dotazu.",
    ["historical_filters_title"] = "Pokročilé filtry",
    ["historical_flows_reach_text"] = "Historické toky žijí pod stejnou ikonou toků na postranním panelu jako živé toky.",
    ["historical_flows_reach_title"] = "Toky",
    ["historical_quick_filter_text"] = "Zadejte, chcete-li přidat značky rychlého filtru – hostitel, protokol, aplikace a další – před spuštěním dotazu.",
    ["historical_quick_filter_title"] = "Rychlý filtr",
