    ["historical_results_title"] = "Záznamy toku",
    ["historical_time_range_text"] = "Dotazujte se na historická data toku z vašeho archivu v jakémkoli minulém okně – předvolby nebo vlastní začátek/konec.",
    ["historical_time_range_title"] = "Vyberte časový rozsah",
    ["interface_charts_text"] = "Místní vs vzdálený provoz a distribuce IPv4/IPv6 pro vybrané rozhraní plus součty, poklesy a využití úložiště níže.",
    ["interface_charts_title"] = "Rozdělení dopravy",
    ["interface_details_reach_text"] = "Vždy se sem můžete vrátit z ikony rozhraní na postranním panelu.",
    ["interface_details_reach_title"] = "Rozhraní",
    ["interface_tabs_text"] = "Sítě, pakety, DSCP, aplikace, kategorie, ICMP, ARP a další – každá karta rozděluje provoz tohoto rozhraní jinak.",
    ["interface_tabs_title"] = "Sekce rozhraní",
    ["live_flows_reach_text"] = "Živé i historické toky jsou k dispozici pod ikonou Toky na postranním panelu. U historických toků se ujistěte, že máte Enterprise M a vyšší s povoleným clickhouse.",
    ["live_flows_reach_title"] = "Toky",
    ["nanalyst_chat_reach_text"] = "Vždy se sem můžete vrátit pomocí ikony nAnalyst na postranním panelu.",
    ["nanalyst_chat_reach_title"] = "nAnalytik",
    ["nanalyst_input_text"] = "Zeptejte se na hostitele, protokoly, toky nebo anomálie v jednoduché angličtině – nAnalyst se dotazuje na vaše provozní údaje a odpovídá přímo.",
    ["nanalyst_input_title"] = "Zeptejte se na cokoli",
    ["nanalyst_new_chat_text"] = "Začněte kdykoli novou konverzaci. Minulé konverzace zůstávají na panelu historie vlevo a lze je filtrovat podle Živých toků nebo Historie.",
    ["nanalyst_new_chat_title"] = "Nová konverzace",
    ["nanalyst_overview_title"] = "Začněte s nAnalyst",
    ["nanalyst_prefs_llm_local_text"] = "Každý poskytovatel – místní/vlastně hostovaný (jakýkoli koncový bod kompatibilní s OpenAI, jako je Ollama, LM Studio, vLLM), Qwen, OpenAI a Anthropic – má stejná tři pole: URL API, název modelu a v případě potřeby token API. Vyplňte, které chcete použít.",
    ["nanalyst_prefs_llm_local_title"] = "Nakonfigurujte poskytovatele",
    ["nanalyst_prefs_llm_text"] = "Kliknutím sem nakonfigurujete místního LLM nebo poskytovatele cloudu (Anthropic, Qwen a další) — API URL, token a název modelu. Toto je nutné, než bude nAnalyst moci odpovídat na otázky.",
    ["nanalyst_prefs_llm_title"] = "Nastavte poskytovatele LLM",
    ["nanalyst_prefs_reach_text"] = "Vždy se sem můžete vrátit pomocí ikony Nastavení na postranním panelu.",
    ["nanalyst_prefs_reach_title"] = "Nastavení",
    ["nanalyst_presets_text"] = "Nevíte, na co se zeptat? Vyberte si jednu z těchto navrhovaných otázek a uvidíte, že nAnalyst okamžitě prozkoumá vaši návštěvnost.",
    ["nanalyst_presets_title"] = "Otázky pro rychlý start",
    ["nanalyst_provider_text"] = "Zde můžete přepínat mezi nakonfigurovanými poskytovateli LLM a modely. Ještě není nastaven žádný poskytovatel? Nakonfigurujte jeden z předvoleb.",
    ["nanalyst_provider_title"] = "Vyberte si svůj model",
    ["nanalyst_rail_invite_text"] = "Pokládejte otázky týkající se síťového provozu v jednoduché angličtině. Kliknutím sem začněte chatovat.",
    ["nanalyst_rail_invite_title"] = "Zkuste nAnalyst",
    ["nanalyst_usage_stats_filters_text"] = "Zúžit statistiky využití podle časového rozsahu, poskytovatele, modelu nebo uživatele – užitečné pro zjištění, který poskytovatel zvyšuje náklady.",
    ["nanalyst_usage_stats_filters_title"] = "Filtrujte své využití",
    ["nanalyst_usage_stats_reach_text"] = "Zde můžete sledovat využití tokenu a náklady na poskytovatele, model a uživatele.",
    ["nanalyst_usage_stats_reach_title"] = "Statistiky použití",
    ["ntopng_overview_title"] = "Vítejte v ntopng",
    ["preferences_main_text"] = "Každé nastavení se zde přepíná nebo upravuje. Změny se projeví okamžitě nebo po restartu, poznamenané podle nastavení.",
    ["preferences_main_title"] = "Nakonfigurujte ntopng",
    ["preferences_reach_text"] = "Vždy se sem můžete vrátit pomocí ikony Nastavení na postranním panelu.",
    ["preferences_reach_title"] = "Nastavení",
    ["preferences_sidebar_text"] = "Předvolby jsou seskupeny podle témat: Upozornění, Aplikace, Oznámení, Záznam provozu, Uživatelské rozhraní a další. Vyhledáním přejdete přímo na nastavení.",
    ["preferences_sidebar_title"] = "Kategorie nastavení",
    ["tour_intro_text"] = "Pojďme si projít to podstatné — Dashboard, Live Flows, Historical Flows a Preferences. Zabere to jen minutu.",
