    ["toggle_tls_quic_hostnaming_description"] = "Jako název hostitele použijte požadovaný TLS/QUIC SNI. Jeho povolením se zefektivní pojmenování hostitelů, ale může do názvů hostitelů vnést falešná pozitiva.",
